public long countPairs(int[] arr, int target) {
    Map<Integer, Integer> freq = new HashMap<>();
    long count = 0;
    for (int x : arr) {
        count += freq.getOrDefault(target - x, 0);
        freq.merge(x, 1, Integer::sum);
    }
    return count;
}
